from fastapi import FastAPI, File, Form
from fastapi.testclient import TestClient
from typing import List

app = FastAPI()

@app.post("/test-order")
async def test_order(form_val: str = Form(...), file_val: bytes = File(...)):
    return {"form_val": form_val, "file_val": file_val}

@app.post("/test-multiple-files")
async def test_multiple_files(form_val: str = Form(...), files: List[bytes] = File(...)):
    return {"form_val": form_val, "files": files}

client = TestClient(app)

def test_form_then_file():
    files = {"file_val": ("filename", b"world")}
    data = {"form_val": "hello"}
    response = client.post("/test-order", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "file_val": "world"}

def test_multiple_files():
    files = [("files", ("f1", b"world1")), ("files", ("f2", b"world2"))]
    data = {"form_val": "hello"}
    response = client.post("/test-multiple-files", data=data, files=files)
    assert response.status_code == 200
    assert response.json() == {"form_val": "hello", "files": ["world1", "world2"]}

if __name__ == "__main__":
    try:
        test_form_then_file()
        print("test_form_then_file passed!")
        test_multiple_files()
        print("test_multiple_files passed!")
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
